const raw = $input.first().json || {};
const body = raw.body || raw;
const isWebhook = Boolean(raw.headers);
const forceNotify = body.force_notify === true;
const dryRun = body.dry_run === true;
return [{
  json: {
    is_webhook: isWebhook,
    force_notify: forceNotify,
    dry_run: dryRun,
    snapshot_payload: {
      jsonrpc: '2.0',
      id: 1,
      method: 'tools/call',
      params: {
        name: 'get_infra_governance_snapshot',
        arguments: {}
      }
    }
  }
}];

const prep = $('Prepare Snapshot Request').first().json;
const resp = $input.first().json;
const text = resp?.result?.content?.[0]?.text || '{}';
const snap = JSON.parse(text);
const kpi = snap.kpi || {};
const evalRun = snap.latest_rag_eval || {};

const anomalies = [];
if (Number(kpi.reconciliation_mismatches || 0) > 0) {
  anomalies.push(`資産 3 点突合の不整合が ${kpi.reconciliation_mismatches} 件`);
}
if (Number(kpi.mfa_coverage_pct || 0) < 100) {
  anomalies.push(`MFA カバレッジ率が ${kpi.mfa_coverage_pct}%（100%未満）`);
}
if (Number(kpi.critical_cves || 0) > 0) {
  anomalies.push(`重大 CVE (CVSS>=9.0) が ${kpi.critical_cves} 件`);
}
if (Number(evalRun.leakage_violations || 0) > 0) {
  anomalies.push(`RAG 漏洩検知が ${evalRun.leakage_violations} 件`);
}
if (evalRun.hit_at_3_pct !== undefined && Number(evalRun.hit_at_3_pct) < 80) {
  anomalies.push(`RAG Hit@3 が ${evalRun.hit_at_3_pct}%（80%未満）`);
}

const status = anomalies.length === 0 ? 'healthy' : 'attention';
const shouldNotify = !prep.dry_run && (anomalies.length > 0 || prep.force_notify);
const discordContent = [
  `${status === 'healthy' ? '✅' : '⚠️'} **[n8n 日次インフラ統制ダイジェスト]** (${kpi.snapshot_date || 'today'})`,
  `- 資産突合: 登録 ${kpi.total_assets ?? '?'} 台 / 不整合 ${kpi.reconciliation_mismatches ?? '?'} 件`,
  `- ID/MFA: 適用率 ${kpi.mfa_coverage_pct ?? '?'}% (${kpi.mfa_enabled_human_users ?? '?'}/${kpi.active_human_users ?? '?'})`,
  `- RAG 品質: Hit@3 ${evalRun.hit_at_3_pct ?? '?'}% / MRR@5 ${evalRun.mrr_at_5 ?? '?'} / 漏洩 ${evalRun.leakage_violations ?? '?'} 件`,
  anomalies.length > 0 ? `- 要確認: ${anomalies.join(' / ')}` : '- 異常なし'
].join('\n');

return [{
  json: {
    ok: true,
    workflow: 'wf02DailyGovDigest',
    status,
    snapshot_date: kpi.snapshot_date || null,
    anomalies,
    should_notify: shouldNotify,
    is_webhook: prep.is_webhook,
    kpi,
    latest_rag_eval: evalRun,
    discord_content: discordContent
  }
}];
